CREATE OR REPLACE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `Products by Category` AS select `Categories`.`CategoryName` AS `CategoryName`,`Products`.`ProductName` AS `ProductName`,`Products`.`QuantityPerUnit` AS `QuantityPerUnit`,`Products`.`UnitsInStock` AS `UnitsInStock`,`Products`.`Discontinued` AS `Discontinued` from (`Categories` join `Products` on(`Categories`.`CategoryID` = `Products`.`CategoryID`)) where `Products`.`Discontinued` <> 1;
